// Some portions generated by Claude
import { createRoot } from "react-dom/client";
import { GraphExplorerApp } from "./GraphExplorerApp.tsx";
import "./graph-explorer.css";

/**
 * The route context the Workbench passes to a route script's mount function (see scriptMount in
 * scripts/ts/workbenchRoutes.ts). Only the members the island uses are typed here.
 */
export type GraphRouteContext = {
  context: { basePath: string; repositoryId: string | null };
  model?: { rows?: unknown[]; vars?: string[] } & Record<string, unknown>;
  url?: URL | string;
};

export type GraphExplorerCleanup = () => void;

const STYLESHEET_ATTRIBUTE = "data-graph-explorer-stylesheet";
const FULL_BLEED_CLASS = "workbench-page-surface--full-bleed";

/** The explorer's stylesheet is built next to its bundle (styles/graph-explorer.css); link it once per document. */
function ensureStylesheet(document: Document, basePath: string) {
  if (document.querySelector(`link[${STYLESHEET_ATTRIBUTE}]`)) {
    return;
  }
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = `${basePath.replace(/\/+$/, "")}/styles/graph-explorer.css`;
  link.setAttribute(STYLESHEET_ATTRIBUTE, "true");
  document.head.appendChild(link);
}

function basePathOf(outlet: HTMLElement, ctx?: GraphRouteContext): string {
  if (ctx?.context?.basePath !== undefined) {
    return ctx.context.basePath;
  }
  const app = outlet.ownerDocument.getElementById("workbench-app");
  return app?.getAttribute("data-workbench-base-path") ?? "";
}

function repositoryIdOf(outlet: HTMLElement, ctx?: GraphRouteContext): string | null {
  if (ctx?.context?.repositoryId) {
    return ctx.context.repositoryId;
  }
  const mount = outlet.querySelector<HTMLElement>("[data-graph-explorer-mount]");
  return mount?.dataset.repositoryId || outlet.ownerDocument.getElementById("workbench-app")?.getAttribute("data-workbench-repository-id") || null;
}

/** Mounts the graph explorer into the route outlet and returns the function that unmounts it again. */
export function mount(outlet: HTMLElement, ctx?: GraphRouteContext): GraphExplorerCleanup {
  const document = outlet.ownerDocument;
  const basePath = basePathOf(outlet, ctx);
  const repositoryId = repositoryIdOf(outlet, ctx);
  ensureStylesheet(document, basePath);
  const host = outlet.querySelector<HTMLElement>("[data-graph-explorer-mount]") ?? outlet;
  const surface = host.closest<HTMLElement>("#workbench-page-surface, .workbench-page-surface");
  surface?.classList.add(FULL_BLEED_CLASS);
  const container = document.createElement("div");
  container.className = "graph-explorer";
  host.appendChild(container);
  // The explorer fills the viewport below the Workbench page header; the header's height is measured, not assumed.
  const view = document.defaultView;
  const sizeToViewport = () => {
    const top = Math.max(0, Math.round(container.getBoundingClientRect().top + (view?.scrollY ?? 0)));
    container.style.setProperty("--graph-explorer-height", `calc(100dvh - ${top}px)`);
  };
  sizeToViewport();
  view?.addEventListener("resize", sizeToViewport);
  const root = createRoot(container);
  if (repositoryId) {
    root.render(<GraphExplorerApp basePath={basePath} repositoryId={repositoryId} />);
  } else {
    root.render(<p className="workbench-empty">Choose a repository to explore it as a graph.</p>);
  }
  return () => {
    view?.removeEventListener("resize", sizeToViewport);
    root.unmount();
    container.remove();
    surface?.classList.remove(FULL_BLEED_CLASS);
  };
}

declare global {
  interface Window {
    workbench?: Record<string, unknown>;
  }
}

if (typeof window !== "undefined") {
  const namespace = (window.workbench ??= {});
  namespace.graphExplorer = { mount };
}
